update public.vt_exercises set media_items='[{"asset_path":"assets/athletics/bridge.png","caption":"Halteposition: Gesäß anspannen und das Becken anheben, bis Schulter, Hüfte und Knie eine Linie bilden. Anschließend kontrolliert absenken.","credit":"Pk0001","source_url":"https://commons.wikimedia.org/wiki/File:Bridge_exercise.svg","license":"CC BY-SA 4.0","license_url":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"SVG als PNG gerastert"}]'::jsonb where exercise_type='athletics' and visibility='system' and name='Beckenheben';
update public.vt_exercises set media_items='[{"asset_path":"assets/athletics/side-plank-start.png","caption":"Ausgangsposition: Seitlich auf den Unterarm stützen, Ellbogen unter der Schulter und Beine lang ausrichten.","credit":"Everkinetic","source_url":"https://commons.wikimedia.org/wiki/File:Side-plank-1.png","license":"CC BY-SA 3.0","license_url":"https://creativecommons.org/licenses/by-sa/3.0/"},{"asset_path":"assets/athletics/side-plank-hold.png","caption":"Halteposition: Becken anheben und den Körper in einer Linie halten. Ruhig weiteratmen, anschließend kontrolliert absenken und die Seite wechseln.","credit":"Everkinetic","source_url":"https://commons.wikimedia.org/wiki/File:Side-plank-2.png","license":"CC BY-SA 3.0","license_url":"https://creativecommons.org/licenses/by-sa/3.0/"}]'::jsonb where exercise_type='athletics' and visibility='system' and name='Seitstütz';
update public.vt_exercises set media_items='[{"asset_path":"assets/athletics/bird-dog.jpg","caption":"Streckposition: Einen Arm und das gegenüberliegende Bein lang ausstrecken. Becken ruhig halten, Kopf in Verlängerung des Rückens und das Bein etwa auf Hüfthöhe führen. Langsam zurückführen und Seite wechseln.","credit":"PTPioneer (Tyler Read)","source_url":"https://commons.wikimedia.org/wiki/File:Bird_dog_exercise.jpg","license":"CC BY 2.0","license_url":"https://creativecommons.org/licenses/by/2.0/","changes":"Verkleinert und JPG komprimiert","author_url":"https://www.ptpioneer.com/"}]'::jsonb where exercise_type='athletics' and visibility='system' and name='Diagonalstrecken im Vierfüßler';
